      "dimensions": [
        "machine",
        "month"
      ],
      "measures": [
        "pm_hours",
        "emergency_hours",
        "cost_m"
      ]
    },
    {
      "dataset": "safety_incidents",
      "description": "رویدادهای ایمنی کارگاه",
      "dimensions": [
        "site",
        "month"
      ],
      "measures": [
        "incidents",
        "near_miss",
        "lost_days"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "oee",
      "description": "کارایی کلی تجهیزات",
      "formula": "دسترس‌پذیری × عملکرد × کیفیت",
      "unit": "درصد",
      "dimensions": [
        "machine"
      ]
    },
    {
      "metric": "otif",
      "description": "تحویل کامل به‌موقع",
      "formula": "سفارش‌های کامل به‌موقع تقسیم بر کل",
      "unit": "درصد",
      "dimensions": [
        "customer"
      ]
    },
    {
      "metric": "emergency_maintenance_ratio",
      "description": "سهم نگهداشت اضطراری",
      "formula": "ساعت اضطراری تقسیم بر کل ساعت نگهداشت",
      "unit": "درصد",
      "dimensions": [
        "machine"
      ]
    }
  ],
  "business_context": [
    "هدف تحویل کامل به‌موقع ۹۵٪ و کارایی تجهیزات ۷۵٪",
    "نگهداشت پیشگیرانه برنامه‌ریزی‌شده دارد ولی اجرا نوسان دارد",
    "دو مشتری سهم بیش از ۳۰٪ سفارش‌ها دارند"
  ]
}
```

برای پاسخ دقیق، این داده را استخراج می‌کنم:
```json
{
  "tool": "get_dataset",
  "arguments": {
    "name": "equipment_oee",
    "filters": {
      "period": "this_month"
    }
  }
}
```

نتیجهٔ داده:
```json
{
  "avg_oee_pct": 70.6
}
```

برای پاسخ دقیق، این داده را استخراج می‌کنم:
```json
{
